//! The secured profile of the IEC 61850 station over TLS (task O4; IEC 62351-3): a served configuration answers its MMS services
//! over a mutually authenticated TLS session, and refuses a client without TLS, a client whose certificate is not trusted, and one
//! whose certificate is revoked. The material is test material (`tests/fixtures/tls`, generated by the sibling repository).

#![cfg(feature = "scl")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects
)]

use std::time::Duration;

use igs_iec61850_mms::model::{client_config, ServedModel};
use igs_iec61850_mms::secure::{secure_station, secured_server_config};
use igs_iec61850_mms_core::scl::build::{build, Capabilities, Configuration};
use igs_iec61850_mms_core::scl::validate::validate;
use igs_iec61850_mms_core::scl::{parse, Limits};
use igs_iso9506_mms::server::Server;
use igs_iso9506_mms::tls::SecureConnector;
use igs_iso9506_mms::vmd::Identity;
use igs_iso9506_mms::Client;
use igs_iso9506_mms_codec::generated::types::{
    AccessResult, Data, Identifier, ObjectName, ObjectNameDomainSpecific, ReadRequest,
    VariableAccessSpecification, VariableAccessSpecificationListOfVariableItem,
    VariableSpecification,
};
use igs_iso9506_mms_link::config::LinkConfig;

const SETTINGS: &str = include_str!("data/settings.cid");
const ROOT: &[u8] = include_bytes!("fixtures/tls/root.pem");
const CRL: &[u8] = include_bytes!("fixtures/tls/crl.pem");
const SERVER: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/server.pem"),
    include_bytes!("fixtures/tls/server.key"),
);
const CLIENT: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/client.pem"),
    include_bytes!("fixtures/tls/client.key"),
);
const ROGUE: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/rogue.pem"),
    include_bytes!("fixtures/tls/rogue.key"),
);
const REVOKED: (&[u8], &[u8]) = (
    include_bytes!("fixtures/tls/revoked.pem"),
    include_bytes!("fixtures/tls/revoked.key"),
);

const ANSWER: Duration = Duration::from_secs(10);
const SGCB: &str = "LLN0$SP$SGCB";

fn configuration() -> Configuration {
    let document = parse(SETTINGS.as_bytes(), &Limits::default()).expect("the document parses");
    validate(&document, "settings.cid").expect("the document is valid");
    build(&document, "settings.cid", "IED1", &Capabilities::current()).expect("the document builds")
}

async fn serving() -> Server {
    let identity = Identity {
        vendor: "igs".to_string(),
        model: "secured".to_string(),
        revision: "1".to_string(),
    };
    let served =
        ServedModel::from_configuration(&configuration(), identity).expect("the model is served");
    let secure = secure_station(Some(SERVER), ROOT, Some(CRL)).expect("the server station");
    Server::bind_model(
        "127.0.0.1:0",
        secured_server_config(LinkConfig::default(), secure),
        served,
    )
    .await
    .expect("the server binds")
}

/// A client over TLS, with the given identity (none to verify the server only).
async fn tls_client(
    server: &Server,
    identity: Option<(&[u8], &[u8])>,
) -> Result<(Client, igs_iso9506_mms::client::Events), igs_iso9506_mms::Error> {
    let secure = secure_station(identity, ROOT, Some(CRL)).expect("the client station");
    let connector = SecureConnector::new(
        server.local_address().to_string(),
        "localhost",
        secure,
        ANSWER,
    );
    tokio::time::timeout(
        ANSWER,
        Client::connect_with(connector, client_config(LinkConfig::default())),
    )
    .await
    .expect("the association is answered in time")
}

fn sgcb_item() -> VariableAccessSpecification {
    VariableAccessSpecification::ListOfVariable(vec![
        VariableAccessSpecificationListOfVariableItem {
            variable_specification: VariableSpecification::Name(ObjectName::DomainSpecific(
                ObjectNameDomainSpecific {
                    domain_id: Identifier("LD1".to_string()),
                    item_id: Identifier(SGCB.to_string()),
                },
            )),
            alternate_access: None,
        },
    ])
}

#[tokio::test]
async fn a_mutually_authenticated_client_reads_the_model_over_tls() {
    let server = serving().await;
    let (client, _events) = tls_client(&server, Some(CLIENT))
        .await
        .expect("the TLS association is accepted");
    let answer = tokio::time::timeout(
        ANSWER,
        client.read(ReadRequest {
            specification_with_result: None,
            variable_access_specification: sgcb_item(),
        }),
    )
    .await
    .unwrap()
    .expect("the read is answered");
    let Some(AccessResult::Success(Data::Structure(parts))) = answer.list_of_access_result.first()
    else {
        panic!("the SGCB is read as a structure: {answer:?}");
    };
    assert_eq!(parts.len(), 6);
}

#[tokio::test]
async fn a_client_without_tls_is_refused_by_the_secured_server() {
    let server = serving().await;
    let plain = tokio::time::timeout(
        ANSWER,
        Client::connect(
            &server.local_address().to_string(),
            client_config(LinkConfig::default()),
        ),
    )
    .await
    .expect("the attempt ends in time");
    assert!(plain.is_err(), "a plain association is refused");
}

#[tokio::test]
async fn a_client_whose_certificate_is_not_trusted_is_refused() {
    let server = serving().await;
    let rogue = tls_client(&server, Some(ROGUE)).await;
    assert!(rogue.is_err(), "a certificate of another root is refused");
}

#[tokio::test]
async fn a_client_whose_certificate_is_revoked_is_refused() {
    let server = serving().await;
    let revoked = tls_client(&server, Some(REVOKED)).await;
    assert!(
        revoked.is_err(),
        "a revoked certificate is refused by the revocation list"
    );
}
